#!/usr/bin/env node
// Snapshots every BSO holder and the current price into chain/src/data/bso-holders.json, the data
// behind chain.bitsocial.net/rich-list/. The page is static, so the snapshot is regenerated by hand
// and committed; nothing is fetched at runtime.
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const BSO_TOKEN_ADDRESS = "0xB50cea4c109dc223A10d44c14f521CaeD91DaB5A";
const BLOCKSCOUT_API = process.env.BLOCKSCOUT_API ?? "https://eth.blockscout.com/api/v2";
const DECIMALS = 18n;

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outputPath = path.join(repoRoot, "chain/src/data/bso-holders.json");

async function getJson(url) {
  for (let attempt = 1; attempt <= 6; attempt += 1) {
    const response = await fetch(url, { headers: { accept: "application/json" } });
    if (response.ok) {
      return response.json();
    }
    if (response.status !== 429 && response.status < 500) {
      throw new Error(`GET ${url} failed with ${response.status}`);
    }
    await new Promise((resolve) => setTimeout(resolve, attempt * 2000));
  }
  throw new Error(`GET ${url} kept failing after retries`);
}

// Four decimals are enough for display and keep the file small.
function toBso(rawValue) {
  const raw = BigInt(rawValue);
  const unit = 10n ** DECIMALS;
  const whole = raw / unit;
  const fraction = (raw % unit) / 10n ** (DECIMALS - 4n);
  return Number(`${whole}.${fraction.toString().padStart(4, "0")}`);
}

async function main() {
  const tokenUrl = `${BLOCKSCOUT_API}/tokens/${BSO_TOKEN_ADDRESS}`;
  console.log(`Fetching token info: ${tokenUrl}`);
  const token = await getJson(tokenUrl);

  const holders = [];
  let nextPageParams = null;
  do {
    const query = nextPageParams ? `?${new URLSearchParams(nextPageParams)}` : "";
    const url = `${BLOCKSCOUT_API}/tokens/${BSO_TOKEN_ADDRESS}/holders${query}`;
    const page = await getJson(url);
    for (const item of page.items) {
      holders.push({
        address: item.address.hash,
        balance: toBso(item.value),
        isContract: Boolean(item.address.is_contract),
      });
    }
    nextPageParams = page.next_page_params;
    console.log(`Fetched ${holders.length} holders`);
    if (nextPageParams) {
      await new Promise((resolve) => setTimeout(resolve, 1200));
    }
  } while (nextPageParams);

  holders.sort((a, b) => b.balance - a.balance);

  const snapshot = {
    generatedAt: new Date().toISOString(),
    source: tokenUrl,
    priceUsd: token.exchange_rate ? Number(token.exchange_rate) : null,
    totalSupply: toBso(token.total_supply),
    holderCount: holders.length,
    holders,
  };

  // One holder per line keeps regenerated snapshots readable in diffs.
  const { holders: holderRows, ...meta } = snapshot;
  const metaLines = Object.entries(meta).map(
    ([key, value]) => `  ${JSON.stringify(key)}: ${JSON.stringify(value)},`,
  );
  const holderLines = holderRows.map((holder) => `    ${JSON.stringify(holder)}`).join(",\n");
  await mkdir(path.dirname(outputPath), { recursive: true });
  await writeFile(
    outputPath,
    `{\n${metaLines.join("\n")}\n  "holders": [\n${holderLines}\n  ]\n}\n`,
  );
  console.log(`Wrote ${holders.length} holders to ${path.relative(repoRoot, outputPath)}`);
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
